public class MortalCoilProjectile : Projectile
	public delegate void ResetEventHandler();
	private static GameObject prefab;
	public Sprite[] tipSprites;
	private bool spriteChanged;
	private bool targetHit;
	private Entity targetEntity;
	public float delayStopwatchTime = 0.125f;
	[HideInInspector]
	public ChaosQuickStopwatch delayStopwatch;
	private bool delayStarted;
	public bool delayCompleted;
	public ResetEventHandler resetEventHandler;
	private int hitCount;
	private Vector2 currentPosition;
