public class NegateProjectiles : MonoBehaviour
	public delegate void GlobalNegateEventHandler(NegateProjectiles negate, Collider2D other, Projectile otherProjectile, string negateSkillCategory);
	public delegate void NegateEventHandler(Collider2D other, Projectile otherProjectile);
	public delegate void GlobalReflectEventHandler(NegateProjectiles negate, Collider2D other, Projectile otherProjectile, string reflectSkillCategory);
	public delegate void ReflectEventHandler(NegateProjectiles negate, Collider2D other);
	public bool reflect;
	public string skillCategory = string.Empty;
	public float damageModifier = 1f;
	public float reflectChance = 1f;
	private Attack attack;
	private Projectile otherScript;
	private Attack otherAttack;
	private List<string> incomingTargetList;
	[HideInInspector]
	public GameObject parentObject;
	[HideInInspector]
	public Animator parentAnim;
	public static GlobalNegateEventHandler globalNegateEventHandlers;
	public NegateEventHandler negateEventHandlers;
	public static GlobalReflectEventHandler globalReflectEventHandlers;
	public ReflectEventHandler reflectEventHandlers;
	[HideInInspector]
	public Vector2 givenNormal;
	private bool initialized;
	private void Awake()
		attack = GetComponent<Attack>();
		givenNormal = Vector2.zero;
	private void Start()
		if (skillCategory == string.Empty && attack != null && attack.atkInfo != null)
			skillCategory = attack.atkInfo.skillCategory;
		initialized = true;
	private void OnTriggerEnter2D(Collider2D other)
		if (!initialized || !(other.transform.parent != null))
			return;
		otherScript = other.transform.parent.GetComponent<Projectile>();
		if (otherScript == null || otherScript.ignoreNegate || otherScript.forcedReturn || (otherScript.parentObject != null && otherScript.parentObject == parentObject) || otherScript.attackBox == null || otherScript.attackBox.atkInfo == null || (reflect && reflectChance < 1f && Random.value > reflectChance))
			return;
		otherAttack = otherScript.attackBox;
		incomingTargetList = otherAttack.atkInfo.targetNames;
		if (skillCategory == otherAttack.atkInfo.skillCategory || (skillCategory.Contains("Player") && !incomingTargetList.Contains(Globals.allyHBStr) && !incomingTargetList.Contains(Globals.allyFCStr)))
			return;
		CameraController.ShakeCamera(0.25f);
		if (reflectEventHandlers != null)
			reflectEventHandlers(this, other);
		if (!reflect || otherScript.ignoreReflect)
			PoolManager.GetPoolItem<HitSparkEmitter>().EmitSingle(HitSparkType.Large, other.transform.position, other.transform.position);
			SoundManager.PlayAudioWithDistance("ImpactNegate", transform.position);
			otherScript.ForceProjectileToReturn();
			if (globalNegateEventHandlers != null)
				globalNegateEventHandlers(this, other, otherScript, skillCategory);
			if (negateEventHandlers != null)
				negateEventHandlers(other, otherScript);
		else if (otherScript.OnReflect(GetReflectedMoveVector(otherScript), damageModifier))
			otherAttack.parentObject = parentObject;
			otherScript.parentObject = parentObject;
			otherAttack.atkInfo.skillCategory = skillCategory;
			otherAttack.atkInfo.targetNames.Add(Globals.allyHBStr);
			otherAttack.atkInfo.targetNames.Add(Globals.enemyHBStr);
			PoolManager.GetPoolItem<ParticleEffect>("ReflectEffect").Emit(1, otherScript.transform.position - (Vector3)otherScript.moveVector * 0.66f, new ParticleSystemOverride
				localEulerAngles = Globals.GetRotationVector(otherScript.moveVector)
			SoundManager.PlayAudioWithDistance("ImpactReflect", transform.position);
			if (globalReflectEventHandlers != null)
				globalReflectEventHandlers(this, other, otherScript, skillCategory);
	private Vector2 GetReflectedMoveVector(Projectile other)
		if (givenNormal == Vector2.zero)
			givenNormal = (other.transform.position - transform.position).normalized;
		return Vector2.Reflect(other.moveVector, givenNormal).normalized;
