public class PhantomArcher : Entity
	private static GameObject prefab;
	private static GameObject projPrefab;
	public Transform bowArm;
	public Transform arrowSpawn;
	public Entity parentEnt;
	public List<GameObject> playerSummonsList;
	public string skillID = string.Empty;
	public int skillLv = 1;
	public Vector2 initDashVec;
	private List<GameObject> targetList;
	private TargetInfo targetInfo;
	private Vector2 currentPos;
	private int delayStopwatchID;
	private int windStopwatchID;
	private int resetStopwatchID;
	private ChaosQuickStopwatch aimStopwatch = new ChaosQuickStopwatch(0.125f);
	private bool isFirstAtk = true;
	private bool dashCompleted;
	private bool atkStarted;
	private bool atkCompleted;
	private bool resetQueued;
	private Projectile currentProj;
	private Vector2 aimVector;
	private Vector3 roteVector;
	private Vector3 armVector;
	private int maxAtkCount = 5;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Effects/PhantomArcher.prefab"));
	private static GameObject ProjPrefab => projPrefab ?? (projPrefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/PhantomArrow.prefab"));
	public override void Awake()
		disablePreventFallCollider = true;
		base.Awake();
	public override void Start()
		base.Start();
		StartDash(initDashVec);
		spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.2f));
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Spawn");
		ChaosBurst.Spawn(currentPos, 3);
	public override void Update()
		if (resetQueued)
			if (ChaosStopwatch.Check(resetStopwatchID))
				Reset();
		else
			if (!dashCompleted)
				return;
			SetXScale();
			if (!ChaosStopwatch.Check(delayStopwatchID))
				return;
			if (!atkStarted)
				atkStarted = true;
				if (!FindTarget())
					EndAttack();
					return;
				if (!isFirstAtk && Vector2.SqrMagnitude(targetInfo.position - transform.position) > 80f)
					atkStarted = false;
					StartDash((targetInfo.position - transform.position).normalized, isReverse: false);
					return;
				anim.Play("AttackWindup", -1, 0f);
				AimTowardsTarget();
				if (isFirstAtk)
					windStopwatchID = ChaosStopwatch.Begin(0.1f);
					return;
				CreateProjectile(arrowSpawn.position, aimVector, 1);
				windStopwatchID = ChaosStopwatch.Begin(Random.Range(0.15f, 0.25f));
				return;
			if (!atkCompleted)
				if (!isFirstAtk)
					AimTowardsTarget();
				if (ChaosStopwatch.Check(windStopwatchID))
					atkCompleted = true;
					AimTowardsTarget(useTimer: false);
					anim.Play("AttackRelease", -1, 0f);
					if (isFirstAtk)
						isFirstAtk = false;
						CreateSpreadShot();
					else
						ReleaseProjectile(currentProj, aimVector);
						currentProj = null;
				return;
			maxAtkCount--;
			if (maxAtkCount > 0)
				atkStarted = false;
				atkCompleted = false;
				if (Random.value < 0.35f)
					StartDash(Random.insideUnitCircle.normalized);
				else
					delayStopwatchID = ChaosStopwatch.Begin(0.1f);
			else
				EndAttack();
	public override void FixedUpdate()
		if (!dashCompleted && movement.DashToTarget())
			dashCompleted = true;
			anim.Play("Slide", -1, 1f);
			movement.MoveToMoveVector(6f);
	private void StartDash(Vector3 givenVec, bool isReverse = true)
		FaceTarget(transform.position + ((!isReverse) ? givenVec : (-givenVec)), 2);
		SetXScale();
		anim.Play((!isReverse) ? "JumpAttackFront" : "Dash", -1, 0f);
		movement.moveVector = givenVec;
		movement.dashVector = givenVec;
		dashCompleted = false;
		delayStopwatchID = ChaosStopwatch.Begin(0.15f);
	private bool FindTarget()
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 12f, playerTagOnly: false, playerSummonsList, parentEnt.gameObject, requireLOS: true, ChaosCollisions.layerUpperWallAndObst);
		if (targetList != null && targetList.Count > 0)
			targetInfo = Entity.GetTargetInfoFromObject(targetList[Random.Range(0, targetList.Count)]);
			targetList.Clear();
			if (targetInfo != null && arrowSpawn != null)
				return true;
		return false;
	private void AimTowardsTarget(bool useTimer = true)
		if (currentProj != null)
			currentProj.transform.position = arrowSpawn.position;
		if ((!useTimer || !aimStopwatch.IsRunning) && targetInfo != null && !(targetInfo.transform == null) && !(targetInfo.hurtBoxTransform == null))
			aimStopwatch.IsRunning = useTimer;
			FaceTarget(targetInfo.transform.position, 2);
			SetXScale();
			aimVector = (targetInfo.hurtBoxTransform.position - arrowSpawn.position).normalized;
			roteVector = Globals.GetRotationVector(aimVector);
			armVector = roteVector;
			if (!isFacingRight)
				armVector.z *= -1f;
			armVector.z += 90f;
			if (bowArm != null)
				bowArm.localEulerAngles = armVector;
			if (!(currentProj == null))
				currentProj.RefreshFlightTime();
				currentProj.transform.localEulerAngles = roteVector;
	private void CreateSpreadShot()
		currentPos = (Vector2)arrowSpawn.position - aimVector * 0.5f;
		for (int i = 0; i < 5; i++)
			CreateProjectile(currentPos, Globals.GetRotatedCircleVector(24, i - 2, aimVector), skillLv, release: true);
	private void CreateProjectile(Vector2 givenPos, Vector2 givenVec, int givenLv, bool release = false)
		currentProj = Projectile.CreateProjectile(parentEnt, ProjPrefab, givenPos, Globals.GetRotationQuaternion(givenVec));
		currentProj.attackBox.SetAttackInfo(skillCategory, skillID, givenLv);
		currentProj.Show();
		currentProj.attackBox.gameObject.SetActive(value: false);
		currentProj.wallCollider.gameObject.SetActive(value: false);
		if (release)
			ReleaseProjectile(currentProj, givenVec, givenDisable: false);
			currentProj = null;
	private void ReleaseProjectile(Projectile givenProj, Vector2 givenVec, bool givenDisable = true)
		if (!(givenProj == null))
			givenProj.transform.localEulerAngles = Globals.GetRotationVector(givenVec);
			givenProj.moveVector = givenVec;
			givenProj.attackBox.knockbackOverwriteVector = givenVec;
			givenProj.attackBox.gameObject.SetActive(value: true);
			givenProj.wallCollider.gameObject.SetActive(value: true);
			givenProj.moveSpeed = 40f;
			givenProj.flyTime = 0.3f;
			givenProj.RefreshFlightTime();
			givenProj.goThroughWalls = false;
			givenProj.disableOnHit = givenDisable;
			givenProj.projectileSpriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, 0.1f));
	private void EndAttack()
		anim.Play("GroundSlam", -1, 0.3f);
		resetStopwatchID = ChaosStopwatch.Begin(0.25f);
		resetQueued = true;
		currentPos = transform.position + Vector3.up;
	private void Reset()
		currentPos = transform.position + Vector3.up;
		PoolManager.GetPoolItem<AnimEffect>("ChaosPortal").Play(currentPos, "Depart");
		string audioID = "EnemyDead";
		Vector2? soundOrigin = currentPos;
		float overridePitch = Random.Range(1.1f, 1.2f);
		Object.Destroy(gameObject);
