			atkStarted = true;
			anim.Play("PBAoE", -1, 1f);
			currentPos = bodyTrans.position;
			switch (maxAtkCount)
			case 1:
				for (int j = -1; j <= 1; j++)
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, j, atkVec));
				break;
			case 2:
				for (int k = 6; k < 10; k++)
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, k, -atkVec));
				break;
			case 3:
				for (int i = -2; i <= 2; i++)
					CreateFireball(currentPos, Globals.GetRotatedCircleVector(15, i, atkVec));
				break;
			delayStopwatchID = ChaosStopwatch.Begin(0.15f);
			return;
		maxAtkCount--;
		if (maxAtkCount > 0)
			atkStarted = false;
			anim.Play("CastAlt", -1, 0f);
			return;
		if (flipForced)
			facingDirection = (isFlipped ? FacingDirection.Right : FacingDirection.Left);
			SetXScale();
